viz.script:
(function(){
  var root=el;
  var cv=root.querySelector('#pfc'), sl=root.querySelector('#pfs'), lab=root.querySelector('#pfk');
  var ctx=cv.getContext('2d');
  var P=[[0.10,0.50,0.30,0.10],[0.20,0.10,0.40,0.30],[0.35,0.25,0.10,0.30],[0.25,0.35,0.20,0.20]];
  var n=4;
  function step(v){var r=[0,0,0,0];for(var j=0;j<n;j++){var s=0;for(var i=0;i<n;i++)s+=v[i]*P[i][j];r[j]=s;}return r;}
  var stat=[1,0,0,0];for(var t=0;t<3000;t++)stat=step(stat);
  var col=['#4C8BF5','#34A853','#FBBC05','#EA4335'];
  function draw(k){var v=[1,0,0,0];for(var t=0;t<k;t++)v=step(v);ctx.clearRect(0,0,600,300);var bw=90,gap=48,x0=70,base=250,h=180;ctx.fillStyle='#555';ctx.textAlign='left';ctx.font='13px sans-serif';ctx.fillText('灰色虚线 = 平稳分布(佩龙向量)',60,28);for(var i=0;i<n;i++){var x=x0+i*(bw+gap);var ys=base-stat[i]*h;ctx.setLineDash([6,4]);ctx.strokeStyle='#999';ctx.beginPath();ctx.moveTo(x-10,ys);ctx.lineTo(x+bw+10,ys);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=col[i];ctx.fillRect(x,base-v[i]*h,bw,v[i]*h);ctx.fillStyle='#222';ctx.textAlign='center';ctx.fillText('状态'+(i+1),x+bw/2,base+18);ctx.fillText(v[i].toFixed(3),x+bw/2,base-v[i]*h-6);}}
  sl.addEventListener('input',function(){lab.textContent=sl.value;draw(+sl.value);});
  draw(0);
})();
